/**
 * ClaudeDockerRunAdapter — DockerRunAdapter specialised for the Claude executor.
 *
 * Owns the Claude executor's env contract: reads Claude-specific runtime
 * requirements directly from process.env and merges them into extraEnv before
 * delegating to the generic DockerRunAdapter. The base class has no knowledge
 * of which executor it is running.
 */

import { DockerRunAdapter, type DockerRunAdapterOpts } from "./docker-run.js";

const CLAUDE_EXECUTOR_PASSTHROUGH = [
  "ANTHROPIC_API_KEY",
  "GIT_AUTHOR_NAME",
  "GIT_AUTHOR_EMAIL",
  "WORKFLOW_LOCAL_PATH",
  "MCP_RAG_URL",
  "GITNEXUS_MCP_URL",
  "FIGMA_PERSONAL_ACCESS_TOKEN",
] as const;

export class ClaudeDockerRunAdapter extends DockerRunAdapter {
  constructor(opts: DockerRunAdapterOpts = {}) {
    const claudeEnv: Record<string, string> = {};
    for (const key of CLAUDE_EXECUTOR_PASSTHROUGH) {
      const val = process.env[key];
      if (val !== undefined) claudeEnv[key] = val;
    }
    super({
      ...opts,
      extraEnv: { ...claudeEnv, ...(opts.extraEnv ?? {}) },
    });
  }
}

async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
  const {
    taskId,
    featureId,
    workspaceId,
    handle,
    taskRepoUrl,
    taskRepoBranch,
    taskBaseBranch,
    taskRepoBaseBranch,
    executorWorkdir,
    mgmtRepoUrl,
    briefingPath,
    resultPath,
    budgetTokens,
    implementationModel,
    sshPrivateKey,
    githubToken,
    callbackUrl,
    nonce,
  } = input;
  const startedAt = new Date().toISOString();
  const containerName = `exec-${handle}`;

  // 1. Register handle with broker before spawning so callback arriving
  //    before submit returns is still accepted.
  if (this.broker) {
    await this.broker.register(handle, nonce, {
      kind: input.kind ?? "impl",
      task_id: taskId,
      feature_id: featureId,
      started_at: startedAt,
    });
  }

  // 2. Build docker run arguments.
  const envArgs: string[] = [
    "-e", `TASK_ID=${taskId}`,
    "-e", `FEATURE_ID=${featureId}`,
    "-e", `WORKSPACE_ID=${workspaceId}`,
    "-e", `TASK_REPO_URL=${taskRepoUrl}`,
    "-e", `TASK_REPO_BRANCH=${taskRepoBranch}`,
    "-e", `TASK_BASE_BRANCH=${taskBaseBranch}`,
    ...(taskRepoBaseBranch !== undefined ? ["-e", `TASK_REPO_BASE_BRANCH=${taskRepoBaseBranch}`] : []),
    "-e", `EXECUTOR_WORKDIR=${executorWorkdir}`,
    "-e", `MGMT_REPO_URL=${mgmtRepoUrl}`,
    "-e", `BRIEFING_PATH=${briefingPath}`,
    "-e", `RESULT_PATH=${resultPath}`,
    "-e", `GITHUB_TOKEN=${githubToken}`,
    "-e", `CALLBACK_URL=${callbackUrl}`,
    "-e", `HANDLE=${handle}`,
    "-e", `NONCE=${nonce}`,
  ];

  if (sshPrivateKey) {
    envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
  }
  if (budgetTokens !== undefined) {
    envArgs.push("-e", `BUDGET_TOKENS=${budgetTokens}`);

