/**
 * SubProcessAdapter — ExecutorPort adapter (Wave 3 / T5).
 *
 * Wave 3 version implements the async runner-callback shape:
 *  - submit() registers the handle with the broker, then spawns the runner
 *    wrapper (T4) as a detached child. Returns the handle immediately without
 *    waiting for the executor to finish.
 *  - Completion arrives via HTTP callback: runner POSTs { handle, nonce, result }
 *    to the broker's /callback endpoint; the orchestrator drains via
 *    broker.listCompleted (T6).
 *  - readResult() is a no-op for this profile — result rides in the callback.
 *  - ack() removes the handle from the supervision map, cleans up the result
 *    file, and delegates to broker.ack.
 *
 * Runner-supervision map:
 *   Keyed by handle; stores (pid, startedAt, nonce, callbackUrl, resultPath).
 *   Purpose: the wrapper-crash safety net only — not in-flight state (the
 *   broker owns that). On child.on('exit'), a grace timer fires; if the
 *   handle is still in the supervision map when the timer fires, the adapter
 *   POSTs a synthetic "failed" completion to the broker on the runner's behalf.
 */

import { spawn } from "node:child_process";
import { unlinkSync, rmSync } from "node:fs";
import { join } from "node:path";
import * as http from "node:http";
import * as https from "node:https";
import type {
  ExecutorPort,
  ExecutorPortInput,
  ExecutorHandle,
  ExecutorResult,
  CompletionBrokerPort,
  HandleKind,
} from "@workflow/runtime-abi";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface SubProcessAdapterOpts {
  /**
   * Path to runner.js (the platform-owned wrapper script from T4).
   * Defaults to the standard location baked into the container image.
   */
  runnerBinPath?: string;

  /**
   * Path to the executor binary. Passed as EXECUTOR_BIN env var to the
   * runner wrapper so it knows what to exec. Defaults to the standard
   * container location; override in tests.
   */
  executorBinPath?: string;

  /**
   * Maximum wall-clock milliseconds before the watchdog kills the runner.
   * Defaults to 2 hours (7_200_000 ms).
   */
  timeoutMs?: number;

  /**
   * Extra environment variables passed to the runner wrapper (and inherited
   * by the executor). Used for single-container extras like
   * GIT_AUTHOR_EMAIL, WORKFLOW_LOCAL_PATH, etc.
   */
  extraEnv?: NodeJS.ProcessEnv;

  /**
   * Host directory under which per-handle exec dirs live.
   * ack() removes `<workspacesDir>/exec-<handle>` after result is processed.
   */
  workspacesDir?: string;

  /**
   * CompletionBrokerPort instance. Required for the full async callback flow.
   * If absent, broker.register is skipped and the adapter operates in
   * broker-less mode (useful for isolated unit tests).
   */
  broker?: CompletionBrokerPort;

  /**
   * Grace window (ms) after child.on('exit') before the safety-net synthetic
   * failure is posted to the broker. This allows a callback that was in-flight
   * at crash time to arrive before we synthesize a failure.
   * Default: 5 000 ms.
   */
  crashGraceMs?: number;

  /**
   * Handle kind registered with the broker. Defaults to "impl".
   * Override to "review" for reviewer executor submissions so the reap loop
   * can route completions to dispatchReviewResult instead of dispatchExecutorResult.
   */
  handleKind?: HandleKind;
}

interface SupervisionEntry {
  pid: number;
  startedAt: string; // ISO 8601
  nonce: string;
  callbackUrl: string;
  resultPath: string;
  taskId: string;
  featureId: string;
}

// ── Defaults ──────────────────────────────────────────────────────────────────

const DEFAULT_RUNNER_BIN = join(
  process.env.EXECUTOR_BIN_PREFIX ?? "/workflow",
  "runtime",
  "runner-wrapper",
  "runner.js",
);

const DEFAULT_TIMEOUT_MS = 7_200_000;
const DEFAULT_CRASH_GRACE_MS = 5_000;

// ── Helpers ───────────────────────────────────────────────────────────────────

function emit(event: Record<string, unknown>): void {
  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
}

/** HTTP POST for the safety-net synthetic failure. Resolves regardless of status. */
function _httpPost(url: string, body: string): Promise<void> {
  return new Promise((resolve, reject) => {
    let u: URL;
    try {
      u = new URL(url);
    } catch {
      reject(new Error(`_httpPost: invalid URL: ${url}`));
      return;
    }
    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(body),
        },
      },
      (res) => {
        res.resume(); // drain the response
        resolve();
      },
    );
    req.on("error", reject);
    req.write(body);
    req.end();
  });
}

// ── SubProcessAdapter ─────────────────────────────────────────────────────────

export class SubProcessAdapter implements ExecutorPort {
  private readonly runnerBinPath: string;
  private readonly executorBinPath: string | undefined;
  private readonly timeoutMs: number;
  private readonly extraEnv: NodeJS.ProcessEnv;
  private readonly broker: CompletionBrokerPort | null;
  private readonly crashGraceMs: number;
  private readonly handleKind: HandleKind;
  private readonly workspacesDir: string | undefined;

  /** Keyed by handle; tracks in-flight runners for the safety-net sweep. */
  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();

  constructor(opts: SubProcessAdapterOpts = {}) {
    this.runnerBinPath = opts.runnerBinPath ?? DEFAULT_RUNNER_BIN;
    this.executorBinPath = opts.executorBinPath;
    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.extraEnv = opts.extraEnv ?? {};
    this.broker = opts.broker ?? null;
    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
    this.handleKind = opts.handleKind ?? "impl";
    this.workspacesDir = opts.workspacesDir;
  }

  // ── ExecutorPort ─────────────────────────────────────────────────────────

  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
    const {
      taskId,
      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch,
      taskBaseBranch,
      taskRepoBaseBranch,
      executorWorkdir,
      mgmtRepoUrl,
      briefingPath,
      resultPath,
      budgetTokens,
      implementationModel,
      sshPrivateKey,
      githubToken,
      callbackUrl,
      nonce,
    } = input;
    const startedAt = new Date().toISOString();

    // 1. Register handle with broker before spawning (broker must record it
    //    before the runner can POST back, else the callback arrives at an
    //    unregistered handle and is rejected 401).
    if (this.broker) {
      await this.broker.register(handle, nonce, {
        kind: input.kind ?? this.handleKind ?? "impl",
        task_id: taskId,
        feature_id: featureId,
        started_at: startedAt,
      });
    }

    // 2. Build environment for the runner wrapper (and inherited by executor).
    const childEnv: NodeJS.ProcessEnv = {
      ...process.env,
      ...this.extraEnv,
      // Formal ABI env vars — passed through to the executor
      TASK_ID: taskId,
      FEATURE_ID: featureId,
      WORKSPACE_ID: workspaceId,
      TASK_REPO_URL: taskRepoUrl,
      TASK_REPO_BRANCH: taskRepoBranch,
      TASK_BASE_BRANCH: taskBaseBranch,
      TASK_REPO_BASE_BRANCH: taskRepoBaseBranch,
      EXECUTOR_WORKDIR: executorWorkdir,
      MGMT_REPO_URL: mgmtRepoUrl,
      BRIEFING_PATH: briefingPath,
      RESULT_PATH: resultPath,
      GITHUB_TOKEN: githubToken,
      ...(sshPrivateKey ? { SSH_PRIVATE_KEY: sshPrivateKey } : {}),
      ...(budgetTokens !== undefined ? { BUDGET_TOKENS: String(budgetTokens) } : {}),
      ...(implementationModel ? { IMPLEMENTATION_MODEL: implementationModel } : {}),
      // Runner wrapper contract (T-Q10)
      CALLBACK_URL: callbackUrl,
      HANDLE: handle,
      NONCE: nonce,
      ...(this.executorBinPath ? { EXECUTOR_BIN: this.executorBinPath } : {}),
    };

    emit({
      type: "executor_spawn",
      task_id: taskId,
      feature_id: featureId,
      handle,
      runner: this.runnerBinPath,
    });

    // 3. Spawn runner wrapper — non-blocking; returns immediately.
    const child = spawn("node", [this.runnerBinPath], {
      env: childEnv,
      stdio: "inherit",
      detached: false,
    });

    // 4. Track in supervision map.
    this.supervision.set(handle, {
      pid: child.pid ?? 0,
      startedAt,
      nonce,
      callbackUrl,
      resultPath,
      taskId,
      featureId,
    });

    // 5. Watchdog: kill runner if it exceeds the wall-clock timeout.
    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
      watchdog = null;
      if (!child.killed) {
        emit({
          type: "executor_timeout",
          task_id: taskId,
          feature_id: featureId,
          handle,
          timeout_ms: this.timeoutMs,
        });
        child.kill("SIGTERM");
      }
    }, this.timeoutMs);
    // Don't hold the event loop open for the watchdog.
    if (watchdog.unref) watchdog.unref();

    // 6. Safety net: if the runner exits without the broker receiving a
    //    callback within crashGraceMs, synthesize a "failed" completion.
    child.on("exit", (code, signal) => {
      if (watchdog !== null) {
        clearTimeout(watchdog);
        watchdog = null;
      }

      emit({
        type: "executor_exit",
        task_id: taskId,
        feature_id: featureId,
        handle,
        exit_code: code,
        signal,
      });

      // Exit code 0 means runner.js completed its postWithRetry successfully —
      // the broker already has the real result. Skip the safety net entirely.
      // The supervision entry stays so ack() can still clean up the result file.
      if (code === 0 && signal === null) {
        return;
      }

      const graceTimer: ReturnType<typeof setTimeout> = setTimeout(() => {
        if (!this.supervision.has(handle)) return; // already acked
        const entry = this.supervision.get(handle)!;
        this.supervision.delete(handle);

        if (!entry.callbackUrl) return; // no callback URL to POST to

        const reason = signal
          ? `runner_killed_by_signal: ${signal}`
          : code !== null && code !== 0
            ? `runner_crashed (exit ${code})`
            : "runner_no_callback";

        emit({
          type: "executor_safety_net",
          task_id: entry.taskId,
          feature_id: entry.featureId,
          handle,
          reason,
        });

        const body = JSON.stringify({
          handle,
          nonce: entry.nonce,
          result: { terminal_status: "failed", blocked_reason: reason },
        });

        _httpPost(entry.callbackUrl, body).catch(() => {
          // Best-effort — ignore POST failures in the safety net.
        });
      }, this.crashGraceMs);

      // Don't hold the event loop open for the grace timer.
      if (graceTimer.unref) graceTimer.unref();
    });

    return handle;
  }

  /**
   * Wave 3: result arrives via broker callback — readResult is a no-op for
   * this profile. Returns a "failed / handle_not_found" tombstone so callers
   * that mistakenly poll readResult get a predictable signal.
   */
  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
  }

  // ── Supervision helpers ───────────────────────────────────────────────────

  /**
   * Acknowledge a completed handle:
   *  - Removes the entry from the supervision map (disarms the safety net).
   *  - Deletes the temp result file written by the executor.
   *  - Delegates to broker.ack to commit consumption in the broker.
   *
   * Call this after the orchestrator has successfully processed the completion
   * returned by broker.listCompleted.
   */
  async ack(handle: ExecutorHandle): Promise<void> {
    const entry = this.supervision.get(handle);
    if (entry) {
      this.supervision.delete(handle);
      try {
        unlinkSync(entry.resultPath);
      } catch {
        // Best-effort — file may already be gone.
      }
      if (this.workspacesDir) {
        try {
          rmSync(join(this.workspacesDir, `exec-${handle}`), { recursive: true, force: true });
        } catch {
          // Best-effort — dir may not exist (e.g. executor never wrote to it).
        }
      }
    }
    if (this.broker) {
      await this.broker.ack(handle);
    }
  }

  /** Number of handles currently tracked in the supervision map. */
  supervisionSize(): number {
    return this.supervision.size;
  }
}

/**
 * SubProcessAdapter — ExecutorPort adapter (Wave 3 / T5).
 *
 * Wave 3 version implements the async runner-callback shape:
 *  - submit() registers the handle with the broker, then spawns the runner
 *    wrapper (T4) as a detached child. Returns the handle immediately without
 *    waiting for the executor to finish.
 *  - Completion arrives via HTTP callback: runner POSTs { handle, nonce, result }
 *    to the broker's /callback endpoint; the orchestrator drains via
 *    broker.listCompleted (T6).
 *  - readResult() is a no-op for this profile — result rides in the callback.
 *  - ack() removes the handle from the supervision map, cleans up the result
 *    file, and delegates to broker.ack.
 *
 * Runner-supervision map:
 *   Keyed by handle; stores (pid, startedAt, nonce, callbackUrl, resultPath).
 *   Purpose: the wrapper-crash safety net only — not in-flight state (the
 *   broker owns that). On child.on('exit'), a grace timer fires; if the
 *   handle is still in the supervision map when the timer fires, the adapter
